import data from "./registry.json";
import { PS_CAPABILITIES, PS_MODES, PS_QUESTION_FORMATS, PS_ROLES, PS_STATUSES, type PsCapability, type PsItemStatus, type PsRegistry } from "./types";

/** The canonical registry (docs/pyspark/plan.md §3). Generated by scripts/pyspark/import-catalog.mjs; statuses are edited in place. */
export const psRegistry = data as PsRegistry;

/**
 * What exists outside the registry: datasets with built, hash-checked editions, and Spark capabilities whose real
 * engine tier passes its acceptance tests. Nothing is live yet, so nothing can be published.
 */
export type PsAvailability = { built: ReadonlySet<string>; live: ReadonlySet<PsCapability> };
export const NOTHING_LIVE: PsAvailability = { built: new Set(), live: new Set() };

const rank = (s: PsItemStatus) => PS_STATUSES.indexOf(s);

/** Every entry that has a status, mode, engine need, prerequisites and datasets, in course order. */
export function trackedItems(reg: PsRegistry = psRegistry) {
  return [
    ...reg.lessons.map((e) => ({ kind: "lesson" as const, ...e })),
    ...reg.questions.map((e) => ({ kind: "question" as const, ...e })),
    ...reg.projects.flatMap((p) => p.milestones.map((e) => ({ kind: "milestone" as const, ...e }))),
  ];
}

/** Structural problems in the registry. Empty means valid. */
export function validatePsRegistry(reg: PsRegistry, available: PsAvailability = NOTHING_LIVE): string[] {
  const problems: string[] = [];
  const seen = new Set<string>();
  const add = (id: string) => (seen.has(id) ? problems.push(`duplicate id ${id}`) : seen.add(id));
  const items = trackedItems(reg);
  const slugs = new Set<string>();
  for (const e of [...reg.lessons, ...reg.projects]) {
    if (slugs.has(`${e.id.slice(3, 4)}:${e.slug}`)) problems.push(`${e.id}: duplicate slug ${e.slug}`);
    slugs.add(`${e.id.slice(3, 4)}:${e.slug}`);
  }
  [...reg.modules, ...reg.projects, ...reg.datasets, ...reg.tools, ...items].forEach((e) => {
    add(e.id);
    if (!e.id.startsWith("PS-")) problems.push(`${e.id}: not namespaced`);
  });

  const datasets = new Map(reg.datasets.map((d) => [d.id, d]));
  const lessons = new Map(reg.lessons.map((l) => [l.id, l]));
  const order = new Map<string, number>(reg.lessons.map((l, i) => [l.id, i]));
  const statusOf = new Map<string, PsItemStatus>(items.map((e) => [e.id, e.status]));
  const modules = new Set(reg.modules.map((m) => m.id));

  for (const m of reg.modules) {
    if (!m.lessons.length) problems.push(`${m.id}: no lessons`);
    for (const l of m.lessons) if (lessons.get(l)?.module !== m.id) problems.push(`${m.id}: lesson ${l} is not in this module`);
  }
  for (const l of reg.lessons) {
    for (const r of l.related) {
      if (!lessons.has(r)) problems.push(`${l.id}: unknown related lesson ${r}`);
      else if (r === l.id || l.prerequisites.includes(r)) problems.push(`${l.id}: ${r} is both related and required`);
    }
    for (const q of l.questions) if (reg.questions.find((x) => x.id === q)?.lesson !== l.id) problems.push(`${l.id}: question ${q} belongs to another lesson`);
  }
  const checkData = (id: string, status: PsItemStatus, refs: readonly string[]) => {
    if (!refs.length) problems.push(`${id}: no dataset`);
    for (const ref of refs) {
      const d = datasets.get(ref as never);
      if (!d) problems.push(`${id}: unknown dataset ${ref}`);
      else if (rank(status) >= rank("reviewed")) {
        // Reviewed or published content must run on data we can ship.
        if (d.licence.status === "review") problems.push(`${id}: ${status} but ${d.id}'s licence isn't cleared`);
        if (!available.built.has(d.id)) problems.push(`${id}: ${status} but ${d.id} has no built fixtures`);
      }
    }
  };
  // Nothing may look runnable before the real Spark tier it needs passes its tests.
  const checkEngine = (id: string, status: PsItemStatus, requires: PsCapability) => {
    if (!PS_CAPABILITIES.includes(requires)) problems.push(`${id}: unknown capability ${requires}`);
    else if (status === "published" && requires !== "none" && !available.live.has(requires)) problems.push(`${id}: published but Spark capability ${requires} isn't live`);
  };

  for (const e of items) {
    if (!PS_STATUSES.includes(e.status)) problems.push(`${e.id}: unknown status ${e.status}`);
    if (!PS_MODES.includes(e.mode)) problems.push(`${e.id}: unknown mode ${e.mode}`);
    if ((e.mode === "read-and-diagnose") !== (e.requires === "none")) problems.push(`${e.id}: mode ${e.mode} doesn't match capability ${e.requires}`);
    if ("module" in e && !modules.has(e.module)) problems.push(`${e.id}: unknown module ${e.module}`);
    if (e.kind === "question") {
      if (!PS_QUESTION_FORMATS.includes(e.format)) problems.push(`${e.id}: unknown format ${e.format}`);
      if (!PS_ROLES.includes(e.role)) problems.push(`${e.id}: unknown role ${e.role}`);
      if (!lessons.has(e.lesson)) problems.push(`${e.id}: unknown lesson ${e.lesson}`);
      else if (!e.prerequisites.includes(e.lesson)) problems.push(`${e.id}: doesn't require its own lesson ${e.lesson}`);
    }
    checkEngine(e.id, e.status, e.requires);
    checkData(e.id, e.status, e.datasets);
    for (const p of e.prerequisites) {
      if (!statusOf.has(p)) problems.push(`${e.id}: unknown prerequisite ${p}`);
      else if (e.kind === "lesson" && (order.get(p) ?? Infinity) >= order.get(e.id)!) problems.push(`${e.id}: prerequisite ${p} comes later`);
      else if (e.status === "published" && statusOf.get(p) !== "published") problems.push(`${e.id}: published before its prerequisite ${p}`);
    }
  }
  for (const p of reg.projects) {
    checkEngine(p.id, p.status, p.requires);
    checkData(p.id, p.status, p.datasets);
    for (const l of p.prerequisites) if (!lessons.has(l)) problems.push(`${p.id}: unknown prerequisite ${l}`);
    if (!p.deliverables.length) problems.push(`${p.id}: no deliverables`);
    if (p.status !== "planned" && p.milestones.length < 3) problems.push(`${p.id}: ${p.status} with ${p.milestones.length} milestones`);
  }
  for (const t of reg.tools) {
    if (!PS_STATUSES.includes(t.status)) problems.push(`${t.id}: unknown status ${t.status}`);
    checkEngine(t.id, t.status, t.requires);
  }
  return problems;
}

/** Every lesson an item depends on, directly or through other lessons. Throws on a cycle. */
export function prerequisiteClosure(ids: readonly string[], reg: PsRegistry = psRegistry): string[] {
  const lessons = new Map<string, (typeof reg.lessons)[number]>(reg.lessons.map((l) => [l.id, l]));
  const done = new Set<string>();
  const walking = new Set<string>();
  const visit = (id: string, path: string[]) => {
    if (done.has(id)) return;
    if (walking.has(id)) throw new Error(`prerequisite cycle: ${[...path, id].join(" → ")}`);
    walking.add(id);
    for (const p of lessons.get(id)?.prerequisites ?? []) visit(p, [...path, id]);
    walking.delete(id);
    done.add(id);
  };
  for (const id of ids) visit(id, []);
  return reg.lessons.map((l) => l.id).filter((id) => done.has(id));
}

/**
 * What stops a learner reaching `ids` (lessons, or a project's prerequisite lessons) along their prerequisites:
 * lessons on datasets whose licence isn't cleared, keyed by dataset.
 */
export function pathwayBlockers(ids: readonly string[], reg: PsRegistry = psRegistry): Record<string, string[]> {
  const datasets = new Map(reg.datasets.map((d) => [d.id, d]));
  const out: Record<string, string[]> = {};
  for (const id of prerequisiteClosure(ids, reg)) {
    for (const d of reg.lessons.find((l) => l.id === id)!.datasets) if (datasets.get(d)?.licence.status === "review") (out[d] ??= []).push(id);
  }
  return out;
}

type Count = Record<string, number>;
const bump = (c: Count, k: string) => void (c[k] = (c[k] ?? 0) + 1);

/** Who uses each dataset, what each engine tier unlocks, and what can't ship yet. */
export function psCoverageReport(reg: PsRegistry = psRegistry, available: PsAvailability = NOTHING_LIVE) {
  const items = trackedItems(reg);
  const datasets = reg.datasets.map((d) => {
    const users = items.filter((e) => e.datasets.includes(d.id));
    return {
      id: d.id,
      title: d.title,
      licence: d.licence.status,
      built: available.built.has(d.id),
      lessons: users.filter((e) => e.kind === "lesson").length,
      questions: users.filter((e) => e.kind === "question").length,
      projects: reg.projects.filter((p) => p.datasets.includes(d.id)).map((p) => p.id),
    };
  });
  const byCapability: Count = {}, byFormat: Count = {}, byStatus: Count = {};
  for (const e of [...items, ...reg.projects.map((p) => ({ ...p, kind: "project" as const })), ...reg.tools.map((t) => ({ ...t, kind: "tool" as const }))]) {
    bump(byCapability, `${e.kind}:${e.requires}`);
    bump(byStatus, `${e.kind}:${e.status}`);
    if (e.kind === "question") bump(byFormat, e.format);
  }
  return {
    datasets,
    unused: datasets.filter((d) => !d.lessons && !d.questions && !d.projects.length).map((d) => d.id),
    blockedByLicence: datasets.filter((d) => d.licence === "review").map((d) => d.id),
    byCapability,
    byFormat,
    byStatus,
  };
}
